impl ShareKind {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		match self {
			ShareKind::File => out.push_str("\"file\""),
			ShareKind::Directory => out.push_str("\"directory\""),
			ShareKind::Other => out.push_str("\"other\""),
		}
	}
	pub fn to_text_into(&self, out: &mut String) {
		match self {
			ShareKind::File => out.push_str("file"),
			ShareKind::Directory => out.push_str("directory"),
			ShareKind::Other => out.push_str("other"),
		}
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		match self {
			ShareKind::File => crate::codec::cbor::text(out, "file"),
			ShareKind::Directory => crate::codec::cbor::text(out, "directory"),
			ShareKind::Other => crate::codec::cbor::text(out, "other"),
		}
	}
}

impl ShareNode {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"handle\":");
		let _ = write!(out, "{}", self.handle);
		out.push(',');
		out.push_str("\"kind\":");
		self.kind.to_json_into(out);
		out.push(',');
		out.push_str("\"size\":");
		let _ = write!(out, "{}", self.size);
		out.push(',');
		out.push_str("\"permissions\":");
		let _ = write!(out, "{}", self.permissions);
		out.push(',');
		out.push_str("\"modified\":");
		let _ = write!(out, "{}", self.modified);
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("handle=");
		let _ = write!(out, "{}", self.handle);
		out.push_str(", ");
		out.push_str("kind=");
		self.kind.to_text_into(out);
		out.push_str(", ");
		out.push_str("size=");
		let _ = write!(out, "{}", self.size);
		out.push_str(", ");
		out.push_str("permissions=");
		let _ = write!(out, "{}", self.permissions);
		out.push_str(", ");
		out.push_str("modified=");
		let _ = write!(out, "{}", self.modified);
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 5);
		crate::codec::cbor::text(out, "handle");
		crate::codec::cbor::uint(out, self.handle as u64);
		crate::codec::cbor::text(out, "kind");
		self.kind.to_cbor_into(out);
		crate::codec::cbor::text(out, "size");
		crate::codec::cbor::uint(out, self.size as u64);
		crate::codec::cbor::text(out, "permissions");
		crate::codec::cbor::uint(out, self.permissions as u64);
		crate::codec::cbor::text(out, "modified");
		crate::codec::cbor::uint(out, self.modified as u64);
	}
}

